import junit.framework.Assert;
import org.junit.Test;
import org.mockito.Mockito;

import java.net.InetSocketAddress;

public class InetSocketAddressTest {
    @Test
    public void testSocketAddress() throws Exception {
        InetSocketAddress address = Mockito.mock(InetSocketAddress.class);
        Mockito.when(address.toString()).thenReturn("address");
        Assert.assertEquals("address", address.toString());
    }
}

